package com.fitnutri.backend.summary;

import com.fitnutri.backend.profile.WeightEntry;
import com.fitnutri.backend.summary.SummaryModels.*;
import java.math.*;
import java.util.*;
import org.springframework.stereotype.Service;

/** Reproducible arithmetic and recorded coverage only. No model, eligibility gate, automatic target or clinical inference. */
@Service
public class RuleSummaryService {
    public List<Fact> buildFacts(PeriodSummary current,PeriodSummary previous,List<WeightEntry> measured){
        List<Fact> facts=new ArrayList<>();var total=current.totals();long foodDays=current.days().stream().filter(d->d.foodCount()>0).count(),activityDays=current.days().stream().filter(d->d.exerciseCount()>0).count();
        facts.add(new Fact("RECORDED_COVERAGE",total.foodCount()==0&&total.exerciseCount()==0?"No food or activity records in this range.":"Food recorded on "+foodDays+" days and activity on "+activityDays+" days of "+current.calendarDayCount()+" calendar days.",values("calendarDayCount",current.calendarDayCount(),"foodRecordedDays",foodDays,"activityRecordedDays",activityDays,"foodCount",total.foodCount(),"exerciseCount",total.exerciseCount())));
        metric(facts,"INTAKE","Recorded intake","kJ",total.intake(),current.averages().intake());metric(facts,"PROTEIN","Recorded protein","g",total.protein(),current.averages().protein());metric(facts,"FAT","Recorded fat","g",total.fat(),current.averages().fat());metric(facts,"CARBS","Recorded carbohydrate","g",total.carbs(),current.averages().carbs());metric(facts,"EXPENDITURE","Recorded activity energy","kJ",total.expenditure(),current.averages().expenditure());
        if(total.activityMinutes()!=null)facts.add(new Fact("RECORDED_ACTIVITY_MINUTES","Recorded activity duration is "+plain(total.activityMinutes())+" minutes; activity counts include entries without energy estimates.",values("minutes",total.activityMinutes(),"knownDayCount",current.averages().activityMinutes().knownDayCount())));
        var goal=current.goalComparison();
        if(goal==null)facts.add(new Fact("NO_EXPLICIT_TARGET","No energy target is set; recorded intake is shown without a goal comparison.",Map.of()));
        else facts.add(new Fact("CURRENT_TARGET_REFERENCE",goal.comparedDays()==0?"No known recorded intake is available for comparison with the current target.":"Known recorded intake is compared with the current target on "+goal.comparedDays()+" dates with known intake; this does not fill unrecorded meals or describe the historical target.",values("dailyTargetKj",goal.dailyTargetKj(),"comparedDays",goal.comparedDays(),"knownIntakeKj",goal.knownIntakeKj(),"targetForComparedDaysKj",goal.targetForComparedDaysKj())));
        var inRange=measured.stream().filter(w->!w.getEntryDate().isBefore(current.rangeStart())&&!w.getEntryDate().isAfter(current.rangeEnd())).sorted(Comparator.comparing(WeightEntry::getEntryDate)).toList();
        if(inRange.size()>=2){var first=inRange.getFirst();var last=inRange.getLast();var change=last.getWeightKg().subtract(first.getWeightKg());var display=change.setScale(1,RoundingMode.HALF_UP);facts.add(new Fact("RECORDED_WEIGHT_CHANGE","Between the recorded weights, change is approximately "+(display.signum()>=0?"+":"")+display.toPlainString()+" kg.",values("fromDate",first.getEntryDate().toString(),"fromKg",first.getWeightKg(),"toDate",last.getEntryDate().toString(),"toKg",last.getWeightKg(),"changeKg",change)));}
        else facts.add(new Fact("INSUFFICIENT_WEIGHT_CHANGE_DATA","At least two recorded weight dates are needed to describe a recorded weight change.",values("recordedDates",inRange.size())));
        if(previous!=null){int before=facts.size();comparison(facts,"INTAKE","Recorded intake","kJ",current,previous,current.averages().intake(),previous.averages().intake());comparison(facts,"EXPENDITURE","Recorded activity energy","kJ",current,previous,current.averages().expenditure(),previous.averages().expenditure());comparison(facts,"ACTIVITY_MINUTES","Recorded activity duration","minutes",current,previous,current.averages().activityMinutes(),previous.averages().activityMinutes());if(facts.size()==before)facts.add(new Fact("INSUFFICIENT_COMPARISON_DATA","There is insufficient known recorded data in both equal-length ranges for a comparison.",values("previousRangeStart",previous.rangeStart().toString(),"previousRangeEnd",previous.rangeEnd().toString())));}
        return List.copyOf(facts);
    }
    private static void metric(List<Fact> facts,String code,String label,String unit,MetricAggregate metric,Average average){if(!metric.hasData())return;String text=metric.knownSum()==null?label+" is unavailable for the recorded items.":label+" has "+plain(metric.knownSum())+" "+unit+" known across "+metric.knownValueCount()+" of "+metric.recordCount()+" records; the recorded-day average is "+plain(average.value())+" "+unit+" across "+average.knownDayCount()+" known days.";facts.add(new Fact(code+"_RECORDED_TOTAL",text,values("knownSum",metric.knownSum(),"recordCount",metric.recordCount(),"knownValueCount",metric.knownValueCount(),"missingValueCount",metric.missingValueCount(),"legacyValueCount",metric.legacyValueCount(),"recordedDayAverage",average.value(),"knownDayCount",average.knownDayCount())));}
    private static void comparison(List<Fact> facts,String code,String label,String unit,PeriodSummary current,PeriodSummary previous,Average a,Average b){if(a.value()==null||b.value()==null)return;var difference=a.value().subtract(b.value());facts.add(new Fact(code+"_AVERAGE_CHANGE",label+" recorded-day average changed by "+plain(difference)+" "+unit+" against the previous equal-length range; each average uses its own known recorded days.",values("currentAverage",a.value(),"previousAverage",b.value(),"difference",difference,"currentKnownDayCount",a.knownDayCount(),"previousKnownDayCount",b.knownDayCount(),"currentRangeStart",current.rangeStart().toString(),"currentRangeEnd",current.rangeEnd().toString(),"previousRangeStart",previous.rangeStart().toString(),"previousRangeEnd",previous.rangeEnd().toString())));}
    private static Map<String,Object> values(Object... pairs){var values=new LinkedHashMap<String,Object>();for(int i=0;i<pairs.length;i+=2)values.put((String)pairs[i],pairs[i+1]);return values;}
    private static String plain(BigDecimal value){return value.stripTrailingZeros().toPlainString();}
}
